const items = $input.all();

return items.map((item) => {
  const data = item.json;
  const host = String(data.hostname || "").toLowerCase();

  const blocked =
    !host ||
    host === "localhost" ||
    host.endsWith(".localhost") ||
    host.endsWith(".local") ||
    host.endsWith(".internal") ||
    host.endsWith(".test") ||
    host.endsWith(".invalid") ||
    host === "metadata.google.internal";

  return {
    json: {
      ...data,
      destinationSafetyChecked: true,
      destinationAllowed: !blocked,
      safetyReason: blocked
        ? "Blocked local or reserved hostname."
        : "Basic hostname check passed; IP-level safety validation is still required."
    }
  };
});

const items = $input.all();

return items.map((item) => {
  const response = item.json;
  const headers = response.headers || {};

  const statusCode = Number(response.statusCode || 0);
  const location = headers.location || headers.Location || null;

  const isRedirect = [301, 302, 303, 307, 308].includes(statusCode);

  return {
    json: {
      statusCode,
      statusMessage: response.statusMessage || "",
      isRedirect,
      location,
      redirectFound: Boolean(isRedirect && location)
    }
  };
});

const items = $input.all();

return items.map((item) => {
  const response = item.json;

  return {
    json: {
      ...response,
      hopCount: 0,
      maxHops: 4,
      redirectHistory: [],
      traceStatus: response.isRedirect
        ? "redirect_detected"
        : "completed",
      nextLocation: response.location || null
    }
  };
});

const items = $input.all();

return items.map((item) => {
  const response = item.json;

  let rdap;

  if (typeof response.data === "string") {
    rdap = JSON.parse(response.data);
  } else {
    rdap = response.data || response;
  }

  const events = Array.isArray(rdap.events) ? rdap.events : [];

  const registrationEvent = events.find(
    (event) => event.eventAction === "registration"
  );

  const registrationDate = registrationEvent
    ? registrationEvent.eventDate
    : null;

  let domainAgeDays = null;

  if (registrationDate) {
    const registered = new Date(registrationDate);
    const now = new Date();

    if (!Number.isNaN(registered.getTime())) {
      domainAgeDays = Math.floor(
        (now.getTime() - registered.getTime()) / 86400000
      );
    }
  }

  return {
    json: {
      domain: rdap.ldhName || null,
      registrationDate,
      domainAgeDays,
      ageLookupStatus: registrationDate
        ? "registration_date_found"
        : "registration_date_unavailable"
    }
  };
});

const items = $input.all();

return items.map((item) => {
  const data = item.json;

  const domain = String(data.domain || "unknown")
    .replace(/[^a-zA-Z0-9.-]/g, "")
    .slice(0, 253);

  const ageDays = Number.isFinite(Number(data.domainAgeDays))
    ? Number(data.domainAgeDays)
    : null;

  const statusCode = Number(data.statusCode || 0);

  const location = data.location
    ? String(data.location).slice(0, 1000)
    : null;

  // Send only the minimum necessary fields to the AI.
  const aiInput = {
    domain,
    domainAgeDays: ageDays,
    statusCode,
    redirectFound: Boolean(data.redirectFound),
    redirectLocationPresent: Boolean(location),
    ageLookupStatus: String(
      data.ageLookupStatus || "unknown"
    )
  };

  return {
    json: {
      ...data,
      aiInput
    }
  };
});

