const items = $input.all();

return items.map((item) => {
  const data = item.json;
  const message = data.message || data;
  const text = String(message.text || "").trim();

  let inputUrl = text;
  let normalizedUrl = "";
  let hostname = "";
  let valid = false;
  let reason = "Invalid URL.";

  try {
    const match = text.match(/https?:\/\/[^\s]+/i);

    if (!match) {
      throw new Error("Please send a full HTTP or HTTPS URL.");
    }

    inputUrl = match[0].replace(/[.,!?]+$/, "");

    const parts = inputUrl.match(
      /^(https?):\/\/([^\/?#:]+)(?::(\d+))?(?:[\/?#]|$)/i
    );

    if (!parts) {
      throw new Error("Invalid URL format.");
    }

    const protocol = parts[1].toLowerCase();
    hostname = parts[2].toLowerCase();
    const port = parts[3] || "";

    if (
      !hostname.includes(".") ||
      hostname === "localhost" ||
      hostname.endsWith(".localhost") ||
      hostname.endsWith(".local") ||
      hostname.endsWith(".internal") ||
      hostname.endsWith(".test") ||
      hostname.endsWith(".invalid")
    ) {
      throw new Error("Local or reserved hostname is not allowed.");
    }

    if (
      /^\d{1,3}(\.\d{1,3}){3}$/.test(hostname) ||
      hostname.startsWith("[")
    ) {
      throw new Error("IP address URLs are not accepted.");
    }

    normalizedUrl =
      protocol + "://" + hostname +
      (port ? ":" + port : "") +
      inputUrl.slice(match[0].indexOf(hostname) + hostname.length + (port ? port.length + 1 : 0));

    valid = true;
    reason = "URL format accepted for further safety checks.";
  } catch (error) {
    reason = error.message;
  }

  return {
    json: {
      tag: "NGP-007",
      inputUrl,
      normalizedUrl,
      hostname,
      valid,
      reason,
      chatId: message.chat?.id ?? data.chat?.id ?? null,
      executionId: String($execution.id),
      receivedAtIST: $now.setZone("Asia/Kolkata").toFormat("yyyy-LL-dd HH:mm:ss"),
      hopCount: 0,
      maxHops: 4,
      redirectHistory: []
    }
  };
});
